// Maili modele gidecek kısa metne indir (gövde 4000 karakterle sınırlı).
return $input.all().map(i => ({ json: {
  tarih: i.json.date ?? '',
  gonderen: i.json.from?.text ?? '',
  konu: i.json.subject ?? '',
  metin: String(i.json.text ?? '').slice(0, 4000),
} }));

// Aynı servisin maillerini birleştir: kaç farklı ayda görüldü, son tutar, aylık karşılığı.
const gruplar = new Map();
$input.all().forEach((item, i) => {
  const o = item.json.output || {};
  if (o.abonelik_mi !== true || !o.servis) return;
  const mail = $('Maili sadeleştir').itemMatching(i).json;
  const tarih = new Date(mail.tarih);
  if (isNaN(tarih)) return;
  const servis = String(o.servis).trim();
  const anahtar = servis.toLocaleLowerCase('tr-TR');
  const g = gruplar.get(anahtar) || { servis, aylar: new Set(), son: null };
  g.aylar.add(tarih.toISOString().slice(0, 7));
  if (!g.son || tarih > g.son.tarih) {
    g.son = { tarih, tutar: Number(o.tutar) || 0, para_birimi: o.para_birimi || '', donem: o.donem || 'bilinmiyor' };
  }
  gruplar.set(anahtar, g);
});
const carpan = { aylik: 1, yillik: 1 / 12, haftalik: 52 / 12 };
const cikti = [...gruplar.values()].map(g => ({ json: {
  servis: g.servis,
  aylik_tutar: Math.round(g.son.tutar * (carpan[g.son.donem] ?? 1) * 100) / 100,
  para_birimi: g.son.para_birimi,
  donem: g.son.donem,
  son_odeme_maili: g.son.tarih.toISOString().slice(0, 10),
  kac_ayda_goruldu: g.aylar.size,
  tekrar_ediyor: (g.aylar.size >= 2 || g.son.donem === 'yillik') ? 'evet' : 'belirsiz',
} }));
cikti.sort((a, b) => b.json.aylik_tutar - a.json.aylik_tutar);
return cikti;
